'use strict';
function renderDashboard(){
  const offline=state.assets.filter(a=>a.operatingState==='Offline');
  const low=state.parts.filter(p=>partOnHand(p)<Number(p.min));
  const openWork=state.workOrders.filter(w=>!['Completed','Cancelled'].includes(w.status));
  const overdue=openWork.filter(w=>w.due&&new Date(w.due)<new Date(new Date().toDateString()));
  const unread=state.notifications.filter(n=>n.userId===CURRENT_USER&&!n.read);
  const purchase=state.purchaseRequests.filter(r=>!['Received','Cancelled','Closed'].includes(r.status));
  return pageHead('Command center','Maintenance overview','A connected operational view of work, asset state, stock risk and purchasing.',
    `<button class="button" data-route="assets">Asset register</button><button class="button primary" data-action="new-work">＋ New work order</button>`)
  +`<div class="grid metrics">
      ${metric('Open work',openWork.length,`${overdue.length} overdue`,overdue.length?'red':'')}
      ${metric('Offline assets',offline.length,offline.length?'Action required':'All tracked assets available',offline.length?'red':'')}
      ${metric('Low-stock parts',low.length,`${purchase.length} purchasing actions`,low.length?'amber':'')}
      ${metric('Unread alerts',unread.length,'In-app maintenance notifications','blue')}
    </div>
    <div class="grid two">
      <section class="card">
        <div class="card-head"><div><h2>Operational exceptions</h2><p>Items that require action now</p></div></div>
        <div class="alert-list" style="padding:12px">
          ${offline.map(a=>`<div class="alert-row unread"><div class="alert-icon">◉</div><div><strong>${esc(a.code)} · ${esc(a.name)} is Offline</strong><small>${esc(a.downtimeReason||'No reason')} · since ${dateTimeFmt(a.offlineSince)}</small></div><button class="button small" data-open-asset="${a.id}">Open</button></div>`).join('')}
          ${low.map(p=>`<div class="alert-row"><div class="alert-icon">◇</div><div><strong>${esc(p.code)} · ${esc(p.name)} below minimum</strong><small>${partOnHand(p)} ${esc(p.uom)} on hand · minimum ${p.min}</small></div><button class="button small" data-open-part="${p.id}">Open</button></div>`).join('')}
          ${!offline.length&&!low.length?'<div class="empty"><strong>No active exceptions</strong><span>Assets and stock levels are within configured limits.</span></div>':''}
        </div>
      </section>
      <section class="card">
        <div class="card-head"><div><h2>My alerts</h2><p>Unread notifications for Abena Sarpong</p></div><button class="button small" data-route="notifications">Open center</button></div>
        <div class="alert-list" style="padding:12px">${unread.slice(0,6).map(n=>`<div class="alert-row unread"><div class="alert-icon">●</div><div><strong>${esc(n.title)}</strong><small>${esc(n.message)}</small></div><time>${dateTimeFmt(n.createdAt)}</time></div>`).join('')||'<div class="empty"><strong>No unread alerts</strong><span>You are caught up.</span></div>'}</div>
      </section>
    </div>
    <div class="grid two" style="margin-top:14px">
      <section class="card">
        <div class="card-head"><div><h2>Priority work</h2><p>Open and in-progress work orders</p></div><button class="button small" data-route="work-orders">View all</button></div>
        ${table(['Work order','Asset','Priority','Status','Due'],openWork.slice(0,6).map(w=>`<tr class="clickable" data-open-work="${w.id}"><td><span class="cell-title">${esc(w.id)}</span><span class="cell-sub">${esc(w.title)}</span></td><td>${esc((getAsset(w.assetIds[0])||{}).name||'—')}</td><td>${status(w.priority)}</td><td>${status(w.status)}</td><td>${dateFmt(w.due)}</td></tr>`),'No open work')}
      </section>
      <section class="card">
        <div class="card-head"><div><h2>Purchase planning</h2><p>Requests generated by stock demand</p></div><button class="button small" data-route="planning">Planning board</button></div>
        ${table(['Request','Part','Qty','Status'],purchase.slice(0,6).map(r=>`<tr><td><span class="cell-title">${esc(r.id)}</span><span class="cell-sub">${esc(r.source)}</span></td><td>${esc(getPart(r.partId)?.code||r.partId)}</td><td>${r.requestedQty}</td><td>${status(r.status)}</td></tr>`),'No purchasing demand')}
      </section>
    </div>`;
}

function renderCalendar(){
  const days=[0,1,2,3,4,5,6].map(o=>day(o));
  return pageHead('Work management','Maintenance calendar','Resource-oriented view of due maintenance work for the next seven days.',
    `<button class="button primary" data-action="new-work">＋ New work order</button>`)
  +`<div class="calendar-grid">${days.map(d=>{
    const items=state.workOrders.filter(w=>w.due===d&&!['Completed','Cancelled'].includes(w.status));
    return `<div class="calendar-day"><h3>${dateFmt(d)}</h3>${items.map(w=>`<div class="calendar-card ${new Date(w.due)<new Date(new Date().toDateString())?'overdue':''}" data-open-work="${w.id}"><strong>${esc(w.id)} · ${esc(w.title)}</strong><small>${esc(w.assigneeIds.map(id=>getUser(id)?.name).filter(Boolean).join(', ')||'Unassigned')}</small></div>`).join('')||'<small class="muted">No scheduled work</small>'}</div>`;
  }).join('')}</div>`;
}

function renderWorkOrders(){
  const q=ui.workSearch.toLowerCase();
  const rows=state.workOrders.filter(w=>(ui.workStatus==='All statuses'||w.status===ui.workStatus)&&(!q||`${w.id} ${w.title} ${w.status} ${w.priority}`.toLowerCase().includes(q)));
  return pageHead('Work management','Work orders','Create, assign, execute and trace maintenance work from one record.',
    `<button class="button primary" data-action="new-work">＋ New work order</button>`)
  +`<section class="card"><div class="toolbar"><input data-filter="work" value="${esc(ui.workSearch)}" placeholder="Search work orders"><select data-work-status><option ${ui.workStatus==='All statuses'?'selected':''}>All statuses</option><option ${ui.workStatus==='Open'?'selected':''}>Open</option><option ${ui.workStatus==='In Progress'?'selected':''}>In Progress</option><option ${ui.workStatus==='Completed'?'selected':''}>Completed</option></select><span class="grow"></span><small class="muted">${rows.length} records</small></div>
    ${table(['Work order','Assets','Type','Priority','Assigned to','Status','Due'],rows.map(w=>`<tr class="clickable" data-open-work="${w.id}"><td><span class="cell-title">${esc(w.id)}</span><span class="cell-sub">${esc(w.title)}</span></td><td>${esc(w.assetIds.map(id=>getAsset(id)?.code||id).join(', '))}</td><td>${esc(w.type)}</td><td>${status(w.priority)}</td><td>${esc(w.assigneeIds.map(id=>getUser(id)?.name).filter(Boolean).join(', ')||'Unassigned')}</td><td>${status(w.status)}</td><td>${dateFmt(w.due)}</td></tr>`),'No work orders')}</section>`;
}
function openWorkDrawer(id){
  const w=getWork(id);if(!w)return;
  openModal({eyebrow:`${w.id} · ${w.type}`,title:w.title,submitText:w.status==='Completed'?'Close':'Update',body:`
    <div class="grid two">
      <div>
        <div class="fields" style="grid-template-columns:repeat(2,1fr)">
          <div class="field"><small>Status</small><strong>${status(w.status)}</strong></div>
          <div class="field"><small>Priority</small><strong>${status(w.priority)}</strong></div>
          <div class="field"><small>Asset</small><strong>${esc(w.assetIds.map(id=>getAsset(id)?.name||id).join(', '))}</strong></div>
          <div class="field"><small>Due</small><strong>${dateFmt(w.due)}</strong></div>
        </div>
        <h3 class="section-title">Instructions</h3><p class="muted" style="font-size:10px;line-height:1.6">${esc(w.instructions||'No instructions')}</p>
        <h3 class="section-title">Tasks</h3>
        ${w.tasks.map(t=>`<div class="setting-row"><div><strong>${esc(t.text)}</strong><small>${esc(t.type)}</small></div>${status(t.status)}</div>`).join('')}
      </div>
      <div>
        <h3 style="margin-top:0;font-size:11px">Planned parts</h3>
        ${w.parts.map(x=>`<div class="setting-row"><div><strong>${esc(getPart(x.partId)?.name||x.partId)}</strong><small>${esc(getPart(x.partId)?.code||'')} · planned ${x.planned}</small></div><span>${x.actual||0} issued</span></div>`).join('')||'<p class="muted">No planned parts.</p>'}
        <h3 class="section-title">History</h3>
        <div class="timeline">${w.history.map(h=>`<div class="event"><strong>${esc(h.text)}</strong><small>${dateTimeFmt(h.at)}</small></div>`).join('')||'<div class="empty"><span>No history yet</span></div>'}</div>
      </div>
    </div>`,
    onSubmit:w.status==='Completed'?null:fd=>{
      if(w.status==='Open') w.status='In Progress';
      else if(w.status==='In Progress'){w.status='Completed';w.completedAt=iso();}
      w.history.unshift({at:iso(),text:`Status changed to ${w.status} by ${currentUser().name}`});
      addAudit('WORK_ORDER_STATUS',w.id,`Status changed to ${w.status}`);saveState();closeModal();render();toast(`${w.id} updated`);
    }});
}

function renderPM(){
  return pageHead('Work management','Scheduled maintenance','Preventive maintenance templates with time and meter triggers and planned material demand.',
    `<button class="button" data-action="add-pm">＋ New scheduled maintenance</button>`)
  +`<section class="card">${table(['Plan','Asset','Trigger','Next due','Parts','Status',''],state.scheduledMaintenance.map(pm=>`<tr><td><span class="cell-title">${esc(pm.id)}</span><span class="cell-sub">${esc(pm.name)}</span></td><td>${esc(getAsset(pm.assetId)?.name||pm.assetId)}</td><td>${esc(pm.triggerType)} · ${esc(pm.trigger)}</td><td>${esc(pm.nextDue)}</td><td>${pm.requiredParts.map(x=>`${esc(getPart(x.partId)?.code||x.partId)} × ${x.qty}`).join(', ')||'—'}</td><td>${status(pm.status)}</td><td class="right"><button class="button small" data-generate-pm="${pm.id}">Generate work</button></td></tr>`),'No scheduled maintenance')}</section>`;
}
function generatePM(id){
  const pm=state.scheduledMaintenance.find(x=>x.id===id);if(!pm)return;
  const asset=getAsset(pm.assetId);
  const wo={id:uid('WO'),title:pm.name,assetIds:[pm.assetId],type:'Preventive',priority:asset?.criticality==='A'?'High':'Medium',status:'Open',assigneeIds:asset?.ownerUserId?[asset.ownerUserId]:[],due:day(2),estimateHours:2,actualHours:0,source:pm.id,instructions:`Generated from scheduled maintenance ${pm.id}.`,tasks:pm.taskTemplate.map(t=>({id:uid('T'),text:t,type:'General',status:'Todo'})),parts:pm.requiredParts.map(x=>({partId:x.partId,planned:x.qty,actual:0})),createdAt:iso(),completedAt:null,history:[{at:iso(),text:`Generated from ${pm.id}`}]};
  state.workOrders.unshift(wo);pm.lastGenerated=iso();
  dispatchEvent('Work order assigned',`${wo.id} assigned`,`${wo.title} was generated from ${pm.id}.`,{assigneeIds:wo.assigneeIds,relatedId:wo.id});
  addAudit('PM_WORK_GENERATED',pm.id,`${wo.id} created`);
  saveState();render();toast(`${wo.id} generated`);
}
function renderRequests(){
  return pageHead('Work management','Requests','Triage operator requests into accountable maintenance work.',
    `<button class="button" data-action="add-request">＋ New request</button>`)
  +`<section class="card">${table(['Request','Asset','Summary','Urgency','Requester','Status',''],state.requests.map(r=>`<tr><td><span class="cell-title">${esc(r.id)}</span><span class="cell-sub">${dateTimeFmt(r.createdAt)}</span></td><td>${esc(getAsset(r.assetId)?.code||r.assetId)}</td><td>${esc(r.summary)}</td><td>${status(r.urgency)}</td><td>${esc(r.requester)}</td><td>${status(r.status)}</td><td class="right">${r.status==='Requested'?`<button class="button small" data-convert-request="${r.id}">Convert to WO</button>`:''}</td></tr>`),'No maintenance requests')}</section>`;
}
function convertRequest(id){
  const r=state.requests.find(x=>x.id===id);if(!r||r.status!=='Requested')return;
  const a=getAsset(r.assetId);
  const w={id:uid('WO'),title:r.summary,assetIds:[r.assetId],type:'Corrective',priority:r.urgency==='Urgent'?'High':'Medium',status:'Open',assigneeIds:a?.ownerUserId?[a.ownerUserId]:[],due:day(r.urgency==='Urgent'?1:3),estimateHours:1,actualHours:0,source:r.id,instructions:`Converted from ${r.id}, requested by ${r.requester}.`,tasks:[{id:uid('T'),text:'Inspect reported issue',type:'Inspection',status:'Todo'}],parts:[],createdAt:iso(),completedAt:null,history:[{at:iso(),text:`Created from ${r.id}`}]};
  state.workOrders.unshift(w);r.status='Converted';r.workOrderId=w.id;
  dispatchEvent('Work order assigned',`${w.id} assigned`,`${w.title} was created from request ${r.id}.`,{assigneeIds:w.assigneeIds,relatedId:w.id});
  addAudit('REQUEST_CONVERTED',r.id,`${w.id} created`);saveState();render();toast(`${r.id} converted to ${w.id}`);
}
